import type { ModelProjection } from './types.ts'
import type { GenerateContextType } from '../../context/generateTypes.ts'
import type { ContentSettings } from '../ContentSettings.ts'
import { normalize } from 'jsr:/@std/path@^1.0.9/normalize'
import type { DefinitionBase } from '../Definition.ts'
import type { IdentifierBase } from '../IdentifierBase.ts'
import type { GeneratedDefinition } from '../GeneratedValue.ts'
import type { GeneratedValue } from '../GeneratedValue.ts'
import type { RefName } from '../../types/RefName.ts'
import { toModelGeneratorKey } from '../GeneratorKeys.ts'
import { DEFAULT_VARIANT } from '../../types/Variant.ts'

type CreateModelArgs<V extends GeneratedValue, EnrichmentType> = {
  context: GenerateContextType
  projection: ModelProjection<V, EnrichmentType>
  refName: RefName
  destinationPath?: string
  rootRef?: RefName
  noExport?: boolean
  /**
   * Target variant of the projection. The Driver resolves the
   * peer's enrichment for this variant, asserts the variant exists
   * (or is the default `'main'` which is always permitted), and
   * threads it into the projection's `ContentSettings`.
   * Optional — omitting it means `'main'`, so variants-unaware
   * callers keep working unchanged.
   */
  variant?: string
}
type ApplyArgs = {
  destinationPath?: string
}

type GetDefinitionArgs = {
  identifier: IdentifierBase
  exportPath: string
  noExport?: boolean
}

/**
 * Driver for the model insertion lifecycle.
 *
 * Resolves the projection's identifier and export path, looks up an
 * existing `Definition` in the target file, instantiates the projection
 * (constructing its value) when no cache hit exists, registers the new
 * definition, and stitches an import into `destinationPath` if it differs
 * from the projection's `exportPath`.
 */
export class ModelDriver<V extends GeneratedValue, EnrichmentType> {
  context: GenerateContextType
  projection: ModelProjection<V, EnrichmentType>
  refName: RefName
  settings: ContentSettings<EnrichmentType>
  destinationPath?: string
  definition: GeneratedDefinition<V>
  rootRef?: RefName
  noExport?: boolean
  variant: string

  constructor({
    context,
    projection,
    refName,
    destinationPath,
    rootRef,
    noExport,
    variant = DEFAULT_VARIANT
  }: CreateModelArgs<V, EnrichmentType>) {
    this.context = context
    this.projection = projection
    this.refName = refName
    this.destinationPath = destinationPath
    this.rootRef = rootRef
    this.noExport = noExport
    this.variant = variant

    this.context.modelDepth[`${projection.id}:${refName}`] = 0

    assertPeerVariantExists({
      context,
      generatorId: projection.id,
      refName,
      variant
    })

    assertPeerSupported({ context, projection, refName, variant })

    this.settings = this.context.toModelContentSettings({ refName, projection, variant })
    this.definition = this.apply({ destinationPath })

    this.context.modelDepth[`${projection.id}:${refName}`] = 0
  }

  private apply({ destinationPath }: ApplyArgs = {}): GeneratedDefinition<V> {
    const { identifier, exportPath } = this.settings

    const definition = this.getDefinition({ identifier, exportPath })

    if (destinationPath && normalize(exportPath) !== normalize(destinationPath)) {
      // Cross-file import of the peer's identifier from its export path.
      // The language builds the import object (`toImport`) and creates the
      // destination file on first write (caller-side); the engine stores
      // via the pure-data `context.register`.
      this.ensureFile(destinationPath)
      this.context.register({
        imports: [this.projection.lang.toImport({ identifier, module: exportPath })],
        destinationPath
      })
    }

    return definition
  }

  /**
   * Ensure the file at `path` exists, creating it on first write through
   * the projection's language — the static read off the projection class
   * at the use site, never persisted (works pre-construction on the
   * cache-hit path). Returns the normalized path.
   */
  private ensureFile(path: string): string {
    const normalizedPath = normalize(path)

    if (!this.context.getFile(normalizedPath)) {
      this.context.addFile(
        this.projection.lang.createFile({ path: normalizedPath, settings: this.context.settings })
      )
    }

    return normalizedPath
  }

  private getDefinition({ identifier, exportPath }: GetDefinitionArgs): DefinitionBase<V> {
    const cachedDefinition = this.context.findDefinition({
      name: identifier.name,
      exportPath
    })

    if (this.affirmDefinition<V>(cachedDefinition, exportPath)) {
      return cachedDefinition
    }

    const value = new this.projection({
      refName: this.refName,
      context: this.context,
      settings: this.settings,
      destinationPath: this.settings.exportPath,
      rootRef: this.rootRef
    })

    const definition = this.projection.lang.toDefinition({
      context: this.context,
      identifier,
      value,
      noExport: this.noExport
    })

    this.ensureFile(exportPath)
    this.context.register({
      definitions: [definition],
      destinationPath: exportPath
    })

    return definition
  }

  private affirmDefinition<V extends GeneratedValue>(
    definition: DefinitionBase | undefined,
    exportPath: string
  ): definition is DefinitionBase<V> {
    if (!definition) {
      return false
    }

    const currentKey = toModelGeneratorKey({
      generatorId: this.projection.id,
      refName: this.refName,
      variant: this.settings.variant
    })

    if (currentKey !== definition.generatorKey) {
      throw new Error(
        `Registered definition mismatch: '${definition.identifier.name}' in file '${exportPath}'. Cached key '${definition.generatorKey}' does not match new key '${currentKey}'`
      )
    }

    return definition.value instanceof this.projection
  }
}

type AssertPeerVariantExistsArgs = {
  context: GenerateContextType
  generatorId: string
  refName: RefName
  variant: string
}

/**
 * Guard the peer-variant-mismatch invariant for model insertions.
 *
 * `'main'` is the universally-safe variant — it's guaranteed to be
 * present on every peer (the engine fills it when no enrichments are
 * configured, and the missing-`'main'` check throws when other
 * variants exist without it). So calls with `variant === 'main'`
 * always succeed regardless of the peer's enrichment shape.
 *
 * For any other variant, the peer's enrichment block at
 * `[generatorId][refName]` must explicitly declare that variant
 * key. The Driver throws here — loud at the call site — rather than
 * letting silently-wrong output reach the consumer.
 */
const assertPeerVariantExists = ({
  context,
  generatorId,
  refName,
  variant
}: AssertPeerVariantExistsArgs): void => {
  if (variant === DEFAULT_VARIANT) {
    return
  }

  const modelEnrichments: unknown = context.readEnrichment([generatorId, refName])

  if (modelEnrichments === null || modelEnrichments === undefined) {
    throw new Error(
      `[${generatorId}] Cannot insert variant '${variant}' for '${refName}' — ` +
        `peer has no enrichments configured. Only '${DEFAULT_VARIANT}' is permitted.`
    )
  }

  if (typeof modelEnrichments !== 'object' || Array.isArray(modelEnrichments)) {
    throw new Error(
      `[${generatorId}] Cannot insert variant '${variant}' for '${refName}' — ` +
        `peer enrichment is not a variant record.`
    )
  }

  if (!(variant in modelEnrichments)) {
    const available = Object.keys(modelEnrichments).join(', ')
    throw new Error(
      `[${generatorId}] Cannot insert variant '${variant}' for '${refName}'. ` +
        `Available variants: ${available}.`
    )
  }
}

type AssertPeerSupportedArgs<V extends GeneratedValue, EnrichmentType> = {
  context: GenerateContextType
  projection: ModelProjection<V, EnrichmentType>
  refName: RefName
  variant: string
}

/**
 * Guard the peer-capability invariant for model insertions.
 *
 * `insertModel` materialises a peer's Definition regardless of the peer's
 * `skip` / `include` configuration — dependency edges are intentionally
 * filter-blind. Capability is different: a peer's `isSupported` declares
 * which models it can serve *at all*. Handing a peer a model it has declared
 * unsupported would build a broken Definition or crash inside the peer's
 * constructor.
 *
 * The Driver throws here instead. The throw unwinds into `GenerateContext`'s
 * per-item `try/catch`, so the *calling* generator's item is recorded as
 * `error` and the run continues — loud, isolated failure rather than silent
 * broken output.
 *
 * A peer that exposes no static `isSupported` is treated as supporting every
 * model: `toModelProjectionBase` defaults it to `() => true`, and a
 * hand-rolled projection may omit it.
 */
const assertPeerSupported = <V extends GeneratedValue, EnrichmentType>({
  context,
  projection,
  refName,
  variant
}: AssertPeerSupportedArgs<V, EnrichmentType>): void => {
  const isSupported = projection.isSupported ?? (() => true)

  if (!isSupported({ refName, context, variant })) {
    throw new Error(
      `[${projection.id}] Cannot insert '${refName}' — peer generator ` +
        `does not support this model (isSupported returned false).`
    )
  }
}

import type { GenerateContextType } from '../../context/generateTypes.ts'
import type { Lang } from '../Lang.ts'
import type { ContentSettings } from '../ContentSettings.ts'
import type { RefName } from '../../types/RefName.ts'
import type { IdentifierType } from '../IdentifierType.ts'
import type { IdentifierBase } from '../IdentifierBase.ts'
import type { GeneratedValue } from '../GeneratedValue.ts'
import type { SchemaToValueFn } from '../../types/TypeSystem.ts'

/**
 * External constructor signature for a model projection class.
 *
 * The pipeline calls `new SomeProjection(args)` with this shape; the
 * runtime base class ({@link ModelProjectionBase}) injects `generatorKey`
 * before calling `super()`.
 */
export type ModelProjectionConstructorArgs<EnrichmentType = undefined> = {
  context: GenerateContextType
  refName: RefName
  settings: ContentSettings<EnrichmentType>
  destinationPath: string
  rootRef?: RefName
}

export type WithTransformModel = {
  transformModel: (refName: RefName) => void
}

export type ToModelEnrichmentsArgs = {
  refName: RefName
  context: GenerateContextType
  /** Model variant whose enrichment should be resolved (see {@link Variant}) */
  variant: string
}

export type TransformModelArgs = {
  context: GenerateContextType
  refName: RefName
  /**
   * The model variant the engine is dispatching for this call. The
   * engine fans out one `transform` call per variant declared in the
   * consumer's `enrichments[id][refName]` block (or just `'main'`
   * when no enrichments are configured). See {@link Variant}.
   */
  variant: string
}

/**
 * Arguments a model generator's `isSupported` predicate receives at the
 * entry/dispatch boundary. The capability counterpart of
 * {@link TransformModelArgs}: it carries the resolved enrichment umbrella so
 * the predicate can gate on user config, but no schema — the predicate
 * resolves the schema itself (`context.resolveSchemaRefOnce(refName, id)`)
 * when it needs it, mirroring how `transform` works.
 */
export type IsSupportedModelArgs = {
  context: GenerateContextType
  refName: RefName
  /** Model variant being probed (see {@link Variant}) */
  variant: string
}

export type ToModelPreviewModuleArgs = {
  context: GenerateContextType
  refName: RefName
  /** Model variant the preview module describes (see {@link Variant}) */
  variant: string
}

export type ToModelMappingArgs = {
  context: GenerateContextType
  refName: RefName
  /** Model variant the mapping module describes (see {@link Variant}) */
  variant: string
}

/**
 * Arguments for a model projection's `toIdentifierName` — the pure,
 * cache-key-source half of the old `toIdentifier`.
 */
export type ToModelIdentifierNameArgs<EnrichmentType = undefined> = {
  refName: RefName
  enrichments: EnrichmentType
  /** Model variant the identifier should disambiguate (see {@link Variant}) */
  variant: string
}

export type ToModelExportPathArgs<EnrichmentType = undefined> = {
  refName: RefName
  enrichments: EnrichmentType
  /** Model variant the export path should disambiguate (see {@link Variant}) */
  variant: string
}

/**
 * Static structural type of a model projection class.
 *
 * Captures both the instance side (`new(...) => V`) and the static side
 * (`id`, `toIdentifierName`, `toIdentifierType`, `toExportPath`,
 * `toEnrichments`, `schemaToValueFn`). Passed as a type parameter to
 * `context.insertModel(...)`.
 */
export type ModelProjection<V extends GeneratedValue, EnrichmentType = undefined> = {
  prototype: V
} & {
  new ({
    context,
    refName,
    settings,
    destinationPath,
    rootRef
  }: ModelProjectionConstructorArgs<EnrichmentType>): V
  id: string
  type: 'model'
  /**
   * The projection's language — the static inherited from the language
   * snippet base the projection class is built on
   * (`toModelProjectionBase(TsSnippet, …)`). Drivers read it
   * pre-construction (cache-hit path). SPIKE (option 2 — see `notes/lang/14`).
   */
  lang: Lang
  /** Pure: the cache-key name. */
  toIdentifierName: (args: ToModelIdentifierNameArgs<EnrichmentType>) => string
  /**
   * Context-aware, overridable: the non-`name` parts of the identifier
   * (`type` / `typeName` / `exported`), derived from the schema. The engine
   * assembles `lang.toIdentifier({ name: toIdentifierName(args),
   * ...toIdentifierType(refName, context) })`.
   */
  toIdentifierType: (refName: RefName, context: GenerateContextType) => IdentifierType
  toExportPath: (args: ToModelExportPathArgs<EnrichmentType>) => string
  toEnrichments: ({ refName, context, variant }: ToModelEnrichmentsArgs) => EnrichmentType
  /**
   * Family-level capability predicate, surfaced as a static by
   * `toModelProjectionBase` (default `() => true`). The Driver probes it on
   * every `insertModel` so a peer is never handed a model it has declared
   * unsupported. Optional: a hand-rolled projection may omit it, in which
   * case it is treated as supporting every model.
   */
  isSupported?: (args: IsSupportedModelArgs) => boolean
  // deno-lint-ignore ban-types
} & Function

/**
 * A {@link ModelProjection} that can also handle **inline** (non-`$ref`)
 * schemas — the parameter type of `insertNormalizedModel`, which is the
 * only consumer of these two statics. `insertModel` (named refs only)
 * takes the plain {@link ModelProjection}, so a generator that never
 * inserts inline schemas declares neither.
 */
export type NormalizedModelProjection<V extends GeneratedValue, EnrichmentType = undefined> =
  ModelProjection<V, EnrichmentType> & {
    /** Builds the inline schema's value (the Definition body). */
    schemaToValueFn: SchemaToValueFn
    /**
     * Builds the Definition's identifier from a bare `fallbackName`. A
     * generator static; returns the neutral `IdentifierBase` (the engine
     * reads only `.name`).
     */
    createIdentifier: (name: string) => IdentifierBase
  }

{
  "name": "@skmtc/gen-zod",
  "version": "0.2.5",
  "exports": "./mod.ts",
  "tasks": {
    "test": "deno test --allow-env --allow-sys --allow-read",
    "test:coverage": "deno test --allow-env --allow-sys --allow-read --coverage=coverage",
    "coverage:report": "deno coverage coverage --lcov --output=coverage.lcov",
    "coverage:html": "deno coverage coverage --html",
    "coverage:check": "deno coverage coverage --detailed",
    "publish": "deno publish --allow-slow-types --allow-dirty"
